-- 연습 콘텐츠 시드 추가 3건 (시나리오 2건, 영상 단계 질문지 1건)
-- 어디서 쓰나: 학습 영역(S06) 목록은 GET /practices(08번)가 practices 테이블을 그대로 보여 주고,
--             연습 열기(S07·S07-2·S08)는 GET /practices/{id}(09번)가 content_json을 내려 준다.
-- 내용 출처: 프론트 mock(frontend/src/api/mock/scenario.ts, unitVideo.ts)의 문구를 그대로 옮겼다.
--   영상 단계(S07-2)는 영상 파일이 프론트에 들어 있어서, 서버에는 질문(questions)과 카드(cards, 영상 3편 제목·설명)만 둔다.
-- 다시 실행해도 같은 행이 중복으로 들어가지 않는다(WHERE NOT EXISTS).
-- 실행 순서: V1 → V2 → V3 → V4 → V5. 새로 추가되는 id는 4, 5, 6이다.
-- 되돌리기: 학습 기록(practice_records)이 아직 없을 때만 DELETE FROM practices WHERE id IN (4, 5, 6);

INSERT INTO practices (type, area, topic, level, title, summary, est_minutes, content_json, sort_order)
SELECT 'SCENARIO', 'HELP', '시나리오 연습', 2, '단톡방에서 받은 곤란한 부탁', '단체 카톡방에서 곤란한 부탁을 받았을 때 내 마음을 지키며 대답해 보는 연습이에요.', 10, '{"scene":"단체 카톡방에 돈을 빌려 달라는 말과 술을 대신 사 달라는 말이 올라와 있고, 한 학생이 입을 가린 채 휴대폰을 보고 있어요.","situation":"단체 카톡방에서 한 친구가 “돈 10만 원만 빌려줄 수 있어? 술 대신 좀 사와”라고 해요.","choices":[{"id":"c1","text":"곤란하다고 솔직하게 말하고 부탁을 거절한다.","follow":"분명하게 거절하는 건 나를 지키는 방법이에요. 친구 사이가 걱정돼도 돈을 빌려주거나 술을 대신 사 주지 않아도 돼요.","hear":"상대에게는 분명한 거절로 들려요. 서운해할 수는 있지만, 부탁을 들어주지 않았다고 내 잘못이 되지는 않아요."},{"id":"c2","text":"대답하지 않고 다른 친구들이 뭐라고 하는지 지켜본다.","follow":"잠깐 숨을 고르는 시간이 될 수 있어요. 다만 계속 재촉받으면 마음이 더 불편해질 수 있어서, 어떻게 답할지 정해 두면 좋아요.","hear":"상대에게는 아직 설득할 수 있다는 신호로 들릴 수 있어요."},{"id":"c3","text":"믿을 수 있는 어른에게 대화를 보여 주고 이야기한다.","follow":"술을 대신 사 달라는 부탁은 혼자 판단하지 않아도 돼요. 대화를 지우지 말고 보여 주면 어떻게 할지 함께 정할 수 있어요.","hear":"걱정이 되어서 도움을 청하는 것으로 들려요."}],"remember":["불편한 마음이 들었다면, 그 느낌은 틀리지 않았어요.","돈을 빌려 달라거나 술·담배를 대신 사 달라는 부탁은 거절해도 괜찮아요.","여러 명이 보는 방에서도 혼자 정하지 않아도 돼요. 믿을 수 있는 사람에게 도움을 구할 수 있어요."],"feelings":[{"id":"f1","label":"불편했어요"},{"id":"f2","label":"헷갈렸어요"},{"id":"f3","label":"괜찮았어요"},{"id":"f4","label":"누군가에게 말하고 싶어졌어요"}]}', 2
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM practices WHERE type = 'SCENARIO' AND area = 'HELP' AND level = 2 AND title = '단톡방에서 받은 곤란한 부탁');

INSERT INTO practices (type, area, topic, level, title, summary, est_minutes, content_json, sort_order)
SELECT 'SCENARIO', 'HELP', '시나리오 연습', 3, '갑자기 늘어난 선물과 칭찬', '갑자기 늘어난 선물과 칭찬이 불편할 때 어떻게 할지 연습해요.', 10, '{"scene":"한 학생이 환하게 웃으며 선물 상자를 내밀고, 다른 학생은 팔을 감싼 채 불편한 표정으로 시선을 피하고 있어요.","situation":"친하지 않던 사람이 갑자기 선물을 주고 칭찬을 늘어놓으며 나에게 특별한 관심을 보여요. 나는 왠지 불편해요.","choices":[{"id":"c1","text":"고맙지만 부담스럽다고 말하고 선물은 받지 않는다.","follow":"불편하다는 마음을 말로 전하는 건 나를 지키는 방법이에요. 상대의 반응이 어떻든, 받고 싶지 않은 선물은 받지 않아도 돼요.","hear":"상대에게는 분명한 경계로 들려요. 서운해할 수는 있지만, 내 마음이 먼저예요."},{"id":"c2","text":"기분이 나쁘지 않으니 일단 받고 어떻게 되는지 지켜본다.","follow":"선물을 받는 것 자체가 잘못은 아니에요. 다만 선물이 점점 늘거나, 답례를 바라거나, 비밀로 하자는 말이 나오는지 살펴보세요.","hear":"상대에게는 내가 관심을 받아들였다는 신호로 들릴 수 있어요."},{"id":"c3","text":"믿을 수 있는 어른에게 이야기하고 어떻게 할지 함께 정한다.","follow":"혼자 판단하지 않아도 돼요. 언제부터, 어떤 선물과 말이 있었는지 이야기하면 함께 살펴볼 수 있어요.","hear":"걱정이 되어서 도움을 청하는 것으로 들려요."}],"remember":["선물, 칭찬, 특별한 관심이 갑자기 늘면 이유를 살펴봐요.","불편한 마음이 들었다면, 그 느낌은 틀리지 않았어요.","비밀로 하자는 말이나 무언가를 바라는 말이 나오면, 멈추고 믿을 수 있는 사람에게 도움을 구할 수 있어요."],"feelings":[{"id":"f1","label":"불편했어요"},{"id":"f2","label":"헷갈렸어요"},{"id":"f3","label":"괜찮았어요"},{"id":"f4","label":"누군가에게 말하고 싶어졌어요"}]}', 3
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM practices WHERE type = 'SCENARIO' AND area = 'HELP' AND level = 3 AND title = '갑자기 늘어난 선물과 칭찬');

INSERT INTO practices (type, area, topic, level, title, summary, est_minutes, content_json, sort_order)
SELECT 'UNIT', 'SAFETY', '안전·자기 보호', 2, '안전·자기 보호', '분명한 단서를 보고 멈추거나 거절하는 연습이에요.', 10, '{"questions":[{"id":"q1","text":"모르는 계정이 “너는 특별해, 우리만 아는 사이 하자”며 계속 메시지를 보내요.","options":[{"id":"a","label":"답장하며 계속 이야기한다"},{"id":"b","label":"답하지 않고 차단한다"},{"id":"c","label":"잘 모르겠어요"}],"compare":{"title":"최고의 선택","best":"b","reason":"특별하다는 말로 가까워진 뒤 비밀을 만들자고 하면 한 번 멈춰야 해요. 답하지 않는 건 나를 지키는 선택이에요."}},{"id":"q2","text":"단톡방에서 “다 같이 하는 거야, 너만 안 하면 이상해”라며 가게 물건을 몰래 가져오자고 해요.","options":[{"id":"a","label":"따라간다"},{"id":"b","label":"하고 싶지 않다고 말하고 빠진다"},{"id":"c","label":"잘 모르겠어요"}],"compare":{"title":"최고의 선택","best":"b","reason":"다 같이 한다는 말에도 하고 싶지 않다고 말해도 괜찮아요. 대화방을 조용히 나와도 돼요."}},{"id":"q3","text":"처음 만난 사람이 “집 앞까지 데려다줄게”라고 해요.","options":[{"id":"a","label":"함께 간다"},{"id":"b","label":"고맙지만 괜찮다고 말하고 믿을 수 있는 사람에게 연락한다"},{"id":"c","label":"잘 모르겠어요"}],"compare":{"title":"최고의 선택","best":"b","reason":"처음 만난 사람에게 사는 곳을 알려 주지 않아도 괜찮아요. 믿을 수 있는 사람과 함께 방법을 정해요."}},{"id":"q4","text":"누가 “이 일은 어른한테 말하면 큰일 나”라고 해요.","options":[{"id":"a","label":"말하지 않고 혼자 지킨다"},{"id":"b","label":"믿을 수 있는 어른에게 말한다"},{"id":"c","label":"잘 모르겠어요"}],"compare":{"title":"최고의 선택","best":"b","reason":"말하지 말라고 하는 일일수록 믿을 수 있는 어른과 나누는 게 좋아요. 첫 문장은 짧아도 충분해요."}},{"id":"q5","text":"마음이 불편한 순간에 잠깐 멈출 수 있어요.","options":[{"id":"a","label":"전혀 아니에요"},{"id":"b","label":"아니에요"},{"id":"c","label":"보통이에요"},{"id":"d","label":"그래요"},{"id":"e","label":"매우 그래요"}],"compare":{"title":"이렇게 생각해 볼 수 있어요","best":null,"reason":"멈추는 건 나를 지키는 신호가 될 수 있어요. 어려운 날도 있어요."}},{"id":"q6","text":"거절한 뒤에 어색해져도 괜찮다고 생각해요.","options":[{"id":"a","label":"전혀 아니에요"},{"id":"b","label":"아니에요"},{"id":"c","label":"보통이에요"},{"id":"d","label":"그래요"},{"id":"e","label":"매우 그래요"}],"compare":{"title":"이렇게 생각해 볼 수 있어요","best":null,"reason":"어색한 마음이 들어도 거절은 잘못이 아니에요. 아직 그렇게 느껴지지 않아도 괜찮아요."}},{"id":"q7","text":"믿을 수 있는 어른이 누구인지 떠올릴 수 있어요.","options":[{"id":"a","label":"전혀 아니에요"},{"id":"b","label":"아니에요"},{"id":"c","label":"보통이에요"},{"id":"d","label":"그래요"},{"id":"e","label":"매우 그래요"}],"compare":{"title":"이렇게 생각해 볼 수 있어요","best":null,"reason":"미리 떠올려 두면 도움이 돼요. 아직 없다면 이음상담소가 함께 찾아 줄 수 있어요."}},{"id":"q8","text":"도움을 청할 때 첫 문장을 말할 수 있어요.","options":[{"id":"a","label":"전혀 아니에요"},{"id":"b","label":"아니에요"},{"id":"c","label":"보통이에요"},{"id":"d","label":"그래요"},{"id":"e","label":"매우 그래요"}],"compare":{"title":"이렇게 생각해 볼 수 있어요","best":null,"reason":"“잠깐 이야기해도 돼요?”처럼 짧은 말로 시작해도 충분해요."}}],"cards":[{"title":"“우리만 아는 사이”라는 말에 멈추기","l1":"특별하다는 말로 가까워진 뒤 비밀을 만들자고 하면 한 번 멈춰 봐요.","l2":"영상에서 어떤 말이 나오는지 먼저 찾아봐요."},{"title":"단톡방에서 하고 싶지 않다고 말하기","l1":"어려운 부탁을 받았을 때 쓸 수 있는 짧은 말을 찾아봐요.","l2":"정답은 하나가 아니에요. 내가 편한 말이면 돼요."},{"title":"멈추고, 믿을 수 있는 어른에게 말 꺼내기","l1":"멈춘 다음에 할 수 있는 일을 순서대로 살펴봐요.","l2":"첫 문장은 짧아도 괜찮아요."}]}', 2
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM practices WHERE type = 'UNIT' AND area = 'SAFETY' AND level = 2 AND title = '안전·자기 보호');

-- 확인: 연습이 6건이고 영역·단계가 아래처럼 나와야 한다.
